/* TooManyItems – tłumaczenia napisów okna (nazwy, opisy i statystyki przedmiotów pochodzą z plików gry).
   Brakujący klucz w danym języku -> angielski. {x} = wstawiana wartość. */
"use strict";

const LOCALE = { Pl_Pl: "pl-PL", En_Us: "en-US", De_De: "de-DE", Fr_Fr: "fr-FR", It_It: "it-IT", Es_Es: "es-ES",
  Pt_Br: "pt-BR", Ru_Ru: "ru-RU", Uk_Ua: "uk-UA", Tr_Tr: "tr-TR", Ja_Jp: "ja-JP", Ko_Kr: "ko-KR",
  Zh_Cn: "zh-CN", Zh_Tw: "zh-TW", Th_Th: "th-TH" };

const slavic = (one, few, many) => (n) => {
  const a = n % 10, b = n % 100;
  if (a === 1 && b !== 11) return `${n} ${one}`;
  if (a >= 2 && a <= 4 && (b < 12 || b > 14)) return `${n} ${few}`;
  return `${n} ${many}`;
};
const simple = (one, other) => (n) => `${n} ${n === 1 ? one : other}`;

